package cn.breezeth.kaleidoscope_grilling;
import com.mojang.serialization.MapCodec;import net.minecraft.core.BlockPos;import net.minecraft.network.chat.Component;import net.minecraft.world.InteractionHand;import net.minecraft.world.ItemInteractionResult;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.BaseEntityBlock;import net.minecraft.world.level.block.RenderShape;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.entity.BlockEntityTicker;import net.minecraft.world.level.block.entity.BlockEntityType;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;
public final class OilPressBlock extends BaseEntityBlock{public static final MapCodec<OilPressBlock> CODEC=simpleCodec(OilPressBlock::new);public OilPressBlock(Properties p){super(p);}@Override protected MapCodec<? extends BaseEntityBlock> codec(){return CODEC;}@Override public RenderShape getRenderShape(BlockState s){return RenderShape.MODEL;}@Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return new OilPressBlockEntity(p,s);}@Override public<T extends BlockEntity>BlockEntityTicker<T>getTicker(Level l,BlockState s,BlockEntityType<T>t){return l.isClientSide?null:createTickerHelper(t,ModBlockEntities.OIL_PRESS.get(),OilPressBlockEntity::serverTick);}@Override protected ItemInteractionResult useItemOn(ItemStack held,BlockState s,Level l,BlockPos p,Player player,InteractionHand hand,BlockHitResult hit){if(!(l.getBlockEntity(p)instanceof OilPressBlockEntity press))return ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;if(held.is(ModItems.OIL_CAKE.get())){if(!l.isClientSide){if(press.addCake()){if(!player.getAbilities().instabuild)held.shrink(1);}else player.displayClientMessage(Component.translatable("message.kaleidoscope_grilling.press_full"),true);}return ItemInteractionResult.SUCCESS;}if(held.isEmpty()&&press.residue()>0){if(!l.isClientSide)player.addItem(new ItemStack(ModItems.OIL_RESIDUE.get(),press.takeResidue()));return ItemInteractionResult.SUCCESS;}if(!l.isClientSide)player.displayClientMessage(Component.translatable("message.kaleidoscope_grilling.press_status",press.cakes(),press.progress(),OilPressBlockEntity.REQUIRED_PROGRESS),true);return ItemInteractionResult.SUCCESS;}}
